from django.db import migrations


def seed_farm_types(apps, schema_editor):

    FarmType = apps.get_model(
        "catalogs",
        "FarmType",
    )

    farm_types = [
        ("RANCH", "Rancho"),
        ("DAIRY", "Lechería"),
        ("FEEDLOT", "Engorda"),
        ("STABLE", "Establo"),
        ("FARM", "Granja"),
    ]

    for code, name in farm_types:

        FarmType.objects.get_or_create(
            code=code,
            defaults={
                "name": name,
            },
        )


def reverse_seed(apps, schema_editor):

    FarmType = apps.get_model(
        "catalogs",
        "FarmType",
    )

    FarmType.objects.filter(
        code__in=[
            "RANCH",
            "DAIRY",
            "FEEDLOT",
            "STABLE",
            "FARM",
        ]
    ).delete()


